//! 🧪️ Finite LIST drafts use the actual donated controller and ordinary prepared controls.
use super::*;
use semio_framework_plugin::{AppRenderOperationContext,ChildContentView};
use semio_framework_ui_contract::{Component,OriginalBuiltTreeRetirement};
use semio_s_artifact_stdio_ifc_4_model::standards::v4::subsets::any::schema::snapshot::{IfcEntity,IfcComplexType};
#[test]
fn donated_finite_list_controller_preserves_explicit_cardinality_exact_words_and_source(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🔎️details/🧪️tests/type-list-input.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){for supplied in [false,true]{let name=row["entity"].as_str().unwrap();let domain=law["domains"].as_array().unwrap().iter().find(|domain|domain["entity"]==name).unwrap();let snapshot=std::sync::Arc::new(IfcSnapshot{entities:vec![IfcEntity{id:1,name:name.into(),args:vec![IfcValue::Unset],complex:domain["ancestors"].as_array().unwrap().iter().map(|name|IfcComplexType{name:name.as_str().unwrap().into(),args:Vec::new()}).collect()}],..Default::default()});let history=semio_framework_plugin::HistoryView::empty();let view=staged_view();let operation=AppRenderOperationContext{app_instance_id:17,base_revision:semio_framework_job::RevisionId(0),generation:semio_framework_job::Generation(1),canonical_base_revision:[0;32],mounted_policy:semio_framework_plugin::app_testing::artifact_app_laws::fixture_mounted_policy()};let doc=semio_framework_async::poll::resolve_ready(ArtifactView::with_render_context(snapshot.as_ref(),&history,ChildContentView::EMPTY,operation,"actual-list-source",None));let mut caller=OriginalWorkFixture::new();let mut work=caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::begin_render_work(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,cx)).unwrap().unwrap();let rows=if supplied{serde_json::json!([{"index":"0","value":{"kind":"aggregate","value":row["words"].as_array().unwrap().iter().map(|bits|serde_json::json!({"kind":"real","value":{"bits":bits}})).collect::<Vec<_>>()}}])}else{serde_json::json!([])};let args=serde_json::json!({"path":"/entities/0","value":{"$ifcType":name,"$ifcInputs":rows}});let parsed=semio_framework_pack_json::parse(&args.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let mut donor=Some(semio_framework_plugin::action_staging::StagedFormRequest{token:semio_framework_plugin::action_staging::StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:view.window_id.as_ref().unwrap().clone(),generation:"1".into(),revision:"0".repeat(64)},locale:view.locale,args:semio_framework_pack_json::to_dsl_value(&parsed),page:None});
  for _ in 0..16{if caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)).unwrap().is_some(){break;}}assert!(donor.is_none());let mut output=None;for _ in 0..1000000{match caller.work_turn(staged_grant(),1000,|cx|Ok(work.render(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,&snapshot,&doc,&view,cx))).unwrap(){Ok(Some(tree))=>{output=Some(tree);break;},Ok(None)=>{},Err(_)=>panic!("LIST draft must stay editable: {}",row["id"])}}
  let tree=output.unwrap();let Component::Extension(status)=&tree.root.children.get(0).unwrap().component else{panic!("original status")};assert_eq!(serde_json::to_value(&status.props).unwrap()["ready"],supplied&&row["admitted"].as_bool().unwrap());let fields=tree.root.children.iter().skip(1).collect::<Vec<_>>();let words=row["words"].as_array().unwrap();assert_eq!(fields.len(),1+if supplied{words.len()}else{0});let Component::Select(cardinality)=&fields[0].children.get(0).unwrap().component else{panic!("explicit length control")};assert_eq!(cardinality.value.as_ref(),if supplied{words.len().to_string()}else{String::new()});assert!(cardinality.items.len()<=32);assert!(!fields[0].children.get(0).unwrap().bindings.is_empty());if supplied{for(field,word)in fields[1..].iter().zip(words){let node=field.children.get(0).unwrap();let Component::Input(props)=&node.component else{panic!("typed member word")};assert_eq!(props.value.as_ref(),word.as_str().unwrap());assert!(!node.bindings.is_empty());}}
  let mut close=OriginalBuiltTreeRetirement::new(tree.root);for _ in 0..1000000{if close.terminal_is_empty(){break;}caller.turn(staged_grant(),|cx|cx.with_original_retirement(|cx|{let demand=close.next_demand(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|close.step(grant))?;Ok(())})).unwrap();}assert!(close.terminal_is_empty());caller.cancel().cancel_now();retire_staged(&mut caller,&mut Some(work));assert_eq!(std::sync::Arc::strong_count(&snapshot),1);caller.finish();}}
}
